/// Every `menu()` declared by a vendored `.dbd`, keyed by its EPICS name.
///
/// This is the table `get_enum_strs` answers a `DBF_MENU` field from: the
/// field's [`FieldDesc::menu`] already points at its choices, and this map
/// exists for the by-name lookups (`.db` loading, `dbpr`).
pub fn menu_choices(menu: &str) -> Option<&'static [&'static str]> {
    Some(match menu {
        "sscanACQM" => MENU_SSCAN_ACQM,
        "sscanACQT" => MENU_SSCAN_ACQT,
        "sscanCMND" => MENU_SSCAN_CMND,
        "sscanDSTATE" => MENU_SSCAN_DSTATE,
        "sscanFAZE" => MENU_SSCAN_FAZE,
        "sscanFFO" => MENU_SSCAN_FFO,
        "sscanFPTS" => MENU_SSCAN_FPTS,
        "sscanLINKWAIT" => MENU_SSCAN_LINKWAIT,
        "sscanNOYES" => MENU_SSCAN_NOYES,
        "sscanP1AR" => MENU_SSCAN_P1_AR,
        "sscanP1NV" => MENU_SSCAN_P1_NV,
        "sscanP1SM" => MENU_SSCAN_P1_SM,
        "sscanPASM" => MENU_SSCAN_PASM,
        "sscanPAUS" => MENU_SSCAN_PAUS,
        _ => return None,
    })
}

